from lib import *
S = SS('t23')
steps = [
    step("一次转账(A 的 100 转 50 给 B)的提交过程。初始已提交:A 和 B 的 data 在 ts=101,write 记录在 commit_ts=102。预写之后(start_ts=103,主锁是 A):data 里多了 ('A', 103, 50) 和 ('B', 103, 50),lock 里有 ('A', 103, 主锁 A) 和 ('B', 103, 主锁 A)——B 的锁指向 A。提交主锁 A 之后(commit_ts=104):write 里多了 ('A', 104, 103),A 的锁没了,B 的锁还在;此刻这个事务已经算提交了。提交次锁 B 之后:write 里多了 ('B', 104, 103),锁全部清掉。新事务(start_ts=105)读到 A = 50、B = 50。整个事务的原子性,押在“主锁那一次提交”上。", t=tl(S(1)), mark=lidx(S(1), '提交主锁 A 之后'), done=lidx(S(1), '提交次锁 B 之后', '新事务'), b=bars([['预写后的锁数', 2, '2(A 主锁、B 次锁)'], ['提交主锁后的锁数', 1, '1(B)'], ['提交次锁后的锁数', 0, '0']], 2, cur=[0], mark=[1], done=[2]), kv=KV([['预写', '每个 key 写 data + lock,次锁指向主锁'], ['提交点', '主锁提交那一刻整个事务提交'], ['次锁', '之后慢慢提交,谁碰到谁帮忙']], ['提交点'])),
    step("快照读与写写冲突(先提交者赢)。T1 先开始(start_ts=103),T2 之后开始并在 commit_ts=105 提交了 x = 2。T1 再读 x 仍然是 1——快照只看得到 start_ts 之前提交的版本;新事务读 x 是 2。T1 想写 x 并提交,预写时发现 x 上有比自己 start_ts 更新的提交记录,写写冲突,中止,并把已写的锁和数据清理干净(lock 行数 0)。这就是快照隔离里“先提交者赢”。", t=tl(S(2)), mark=lidx(S(2), 'T1 提交:预写失败'), done=lidx(S(2), 'T1(start_ts=103)读 x = 1'), b=bars([['T1 快照读到的 x', 1, '1(旧版本)'], ['新事务读到的 x', 2, '2'], ['T1 提交后遗留的锁行数', 0, '0']], 2, cur=[0, 1], done=[2]), kv=KV([['快照读', '只看到 start_ts 之前提交的'], ['写写冲突', '更新的提交记录 → 中止'], ['先提交者赢', 'T2 赢,T1 重来']], ['先提交者赢'])),
    step("客户端在预写之后、提交主锁之前被 kill -9。kill 之后库里是 data 里的两个新版本(ts=103)、lock 里的 A 与 B 两把锁、write 里没有新的提交记录。新事务读 B:发现 B 上有 start_ts 之前的锁,去看主锁 A——还在、TTL(1500 ms)没过期,主锁可能属于一个正在进行的事务,只能等;轮询 107 次、等了 1486 ms,锁过期之后把整个事务回滚(回滚了 1 把锁并顺带清掉 A 的锁),读到 B = 0;再读 A = 100,lock 行数 0。没人提交的事务,等到 TTL 之后由读到它的人回滚。", t=tl(S(3)), mark=lidx(S(3), '新事务读 B'), done=lidx(S(3), '再读 A = 100'), b=bars([['读 B 等待 ms', 1486, '1486'], ['锁 TTL ms', 1500, '1500'], ['等待轮询次数', 107, '107']], 1500, cur=[0], mark=[1], done=[2]), kv=KV([['kill -9 于预写之后', '两把锁遗留在库里'], ['读到锁', '主锁没过期就等,过期就回滚'], ['结果', 'A = 100、B = 0,事务没发生']], ['结果'])),
    step("客户端在提交主锁之后、提交次锁之前被 kill -9。库里:write 里 A 有了 commit_ts=104 的提交记录,B 还有一把指向 A 的锁。只看提交记录、不管锁的读:A = 50、B = 0,合计 50(应该是 100)——看到了转账的一半。会处理锁的读:读 B 时发现锁,去看主锁 A,A 已经提交,就前滚——把 B 的锁换成提交记录,不用等,用时 0.7 ms,读到 B = 50、A = 50,合计 100。主锁一提交事务就算提交,次锁只是个遗留物,谁碰到谁收尾。", t=tl(S(4)), mark=lidx(S(4), '只看提交记录'), done=lidx(S(4), '会处理锁的读'), b=bars([['不管锁的读:合计', 50, '50(应为 100)'], ['会处理锁的读:合计', 100, '100'], ['前滚读 B 用时 ms', 0.7, '0.7']], 100, mark=[0], done=[1], cur=[2]), kv=KV([['不管锁的读', '看到转账的一半(合计 50)'], ['处理锁的读', '前滚,不等待,合计 100'], ['原子性', '押在主锁那一次提交上']], ['原子性'])),
    step("压力下的一致性:10 个账户各 100(总额 1000),6 个线程各做 100 次随机转账,每次有 5% 概率在预写之后“崩溃”(留下锁)、5% 概率在主锁提交之后“崩溃”,另有读线程不断对全部账户做快照读并检查总额。600 次转账用时 4.0 s:提交 310、写写冲突中止 260、预写后崩溃 15、主锁提交后崩溃 15。读线程处理锁:前滚 69 次、回滚 34 次、等待轮询 2016 次。会处理锁的快照读检查了 215 次,总额不是 1000 的 0 次;不管锁的读检查了 3339 次,总额不是 1000 的 11 次。全部处理完之后的最终快照合计 1000,lock 行数 0。", t=tl(S(5)), mark=lidx(S(5), '不管锁的读'), done=lidx(S(5), '会处理锁的快照读', '全部处理完之后'), b=bars([['会处理锁的读:总额错误次数', 0, '0 / 215'], ['不管锁的读:总额错误次数', 11, '11 / 3339'], ['提交的转账', 310, '310'], ['写写冲突中止', 260, '260']], 320, done=[0], mark=[1], cur=[2, 3]), kv=KV([['会处理锁的快照读', '215 次检查,0 次错'], ['不管锁的读', '3339 次检查,11 次错'], ['最终', '合计 1000,锁清空']], ['最终'])),
]
A = mkartt('t23', 23, '分布式事务,Percolator,主锁,次锁,快照隔离,MySQL,真实验证,动画演示',
    '手写最小的 Percolator 风格事务并实测:原子性押在主锁那一次提交上;预写后 kill -9,读到的人等 1486 ms(TTL 1500 ms)后回滚;主锁提交后 kill -9,读到的人 0.7 ms 前滚;压力下会处理锁的快照读 215 次检查总额 0 次错,不管锁的读 3339 次错 11 次。',
    'Percolator 用“主锁 + 次锁”让一个事务跨多行(多个分片)原子提交,不需要独立的协调者进程。它怎么提交?客户端崩溃后谁来收尾?读到别人的锁怎么办?这篇自己实现一个最小版本(单机 MySQL 模拟存储),用 kill -9 和压力测试把这些路径逐个跑出来。',
    [('1486 ms', '预写后客户端 kill -9,读到遗留的锁的新事务等到主锁过期(TTL 1500 ms)后回滚所花的时间'), ('0.7 ms', '主锁已提交、次锁遗留时,读到次锁的新事务前滚所花的时间(不用等)'), ('0 / 215 vs 11 / 3339', '压力下总额不是 1000 的快照读次数:会处理锁的读 vs 不管锁的读')],
    [('主锁与次锁', '<p>预写时每个 key 写 data 和 lock,次锁记着主锁在哪;提交主锁的那一次本地事务就是整个事务的提交点。</p>'),
     ('快照与冲突', '<p>读只看 start_ts 之前提交的版本;预写时发现更新的提交记录或别人的锁,就中止(先提交者赢)。</p>'),
     ('客户端死在提交之前', '<p>锁遗留在库里,碰到的人看主锁:未过期就等,过期就回滚整个事务。</p>'),
     ('客户端死在提交主锁之后', '<p>事务已经提交,碰到遗留次锁的人看一眼主锁就前滚,不用等。</p>'),
     ('压力下的一致性', '<p>每个读都先处理遇到的锁,快照读的总额始终正确;只看提交记录不管锁的读会看到半个事务。</p>')],
    steps,
    [ENV_T + '。本篇是我自己写的最小实现(tools/articles/percolator.py,Python + MySQL 26.7.0,READ COMMITTED 隔离级别),不是 Google 的 Percolator,也不是 TiKV / TiDB;存储是同一个 MySQL 里的 data / lk / wr 三张表,时间戳来自 tso 表里一行的原子自增,锁 TTL 第 3 节是 1500 ms、第 5 节是 300 ms;“崩溃”有两种:真正的 kill -9 子进程(第 3、4 节)和代码里直接不再往下做(第 5 节);提交主锁、回滚抢锁靠“谁删到锁行谁说了算”',
     '没有验证:TiKV / TiDB 的实际实现(异步提交、1PC、悲观事务、大事务的处理);存储分布在多个节点、TSO 是独立服务时的延迟;锁 TTL 的续期(这里没有 heartbeat);读到锁时的等待策略(这里是轮询);初版压力测试里最终总额是 894(不是 1000),说明实现有错;我据此改了两处——预写时先加锁再检查写冲突、改用读已提交并按“先读主锁、后读提交记录”的顺序判断——改后总额才对,最终数字是改后的结果;这两处改动各自起了多大作用,我没有分别验证'],
    'Percolator')
